import{_ as a,o as r,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-12-04 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2019-12-04 :: Ceph Developer Monthly","date":"2019-12-04T00:00:00.000Z","updated":"2019-12-06T00:00:00.000Z","tags":["Ceph","Orchestrator","自动化","分布式存储","集群管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-04_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2019/2019-12-04_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-12-04_-_-_Ceph_Developer_Monthly.md"};function i(h,e,s,n,p,_){return r(),t("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要围绕Ceph的Orchestrator功能展开讨论，重点关注其与NDS交付内容的交互方式、部署流程、监控系统集成等多个方面，旨在简化Ceph集群的部署和管理流程。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Orchestrator功能介绍</strong>：</p><ul><li>Orchestrator提供了一个通用的API和代码层，支持通过Rook或SSH部署守护进程，简化集群安装和日常运维。</li><li>目标是减少步骤，提供完整的集群安装体验，并支持磁盘更换、节点添加/移除等操作。</li></ul></li><li><p><strong>部署流程简化</strong>：</p><ul><li>讨论了使用Orchestrator API标准化部署流程，减少对第三方工具的依赖，使部署和维护更加容易。</li><li>探讨了容器化部署的优势，简化了包管理过程。</li></ul></li><li><p><strong>监控系统集成</strong>：</p><ul><li>讨论了Prometheus和Grafana的部署和集成，以及如何通过Orchestrator管理这些监控组件。</li><li>探讨了如何在Ceph集群中集成外部监控系统，以及如何处理容器和物理主机之间的监控数据。</li></ul></li><li><p><strong>升级和维护</strong>：</p><ul><li>讨论了集群升级的流程，包括如何检查和执行升级，以及如何处理升级过程中的暂停和恢复。</li><li>提出了通过Orchestrator API进行声明式管理的可能性，以简化操作和维护。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了Orchestrator的核心功能和目标，包括简化部署流程和提供完整的集群管理功能。</li><li>确定了监控系统的基本集成方案，包括Prometheus和Grafana的部署和管理。</li><li>讨论了升级流程的实现细节，包括如何通过Orchestrator API进行管理和控制。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续完善Orchestrator的功能，特别是监控系统的集成和升级流程的实现。</li><li>探索通过Orchestrator API进行声明式管理的可能性，以进一步简化操作和维护。</li><li>考虑重命名当前的部署工具，以更好地反映其功能和用途。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li>讨论了MDS（Metadata Server）的亲和性和可用性区域的配置。</li><li>探讨了如何在Ceph集群中集成外部监控系统，以及如何处理容器和物理主机之间的监控数据。</li></ul><p>本次会议为Ceph的Orchestrator功能的发展和集成提供了明确的方向和行动计划，旨在进一步简化Ceph集群的部署和管理流程，提高效率和可靠性。</p>',12)])])}const u=a(o,[["render",i]]);export{d as __pageData,u as default};
